using System.Text.Json;
using Microsoft.AspNetCore.Http;

namespace QuickCode.Quickcode.Infrastructure.Web.Helpers;

public static class JsonErrorResponseWriter
{
    public static async Task WriteAsync(HttpContext context, int statusCode, string message, string? redirectUrl = null)
    {
        if (context.Response.HasStarted)
            return;

        // Native browser username/password dialogs appear for XHR 401 when
        // WWW-Authenticate is present (and some agents treat bare 401 similarly).
        // Session-expired AJAX redirects use 403 + redirectUrl instead.
        context.Response.Headers.Remove("WWW-Authenticate");

        var httpStatus = statusCode;
        if (statusCode == StatusCodes.Status401Unauthorized && !string.IsNullOrEmpty(redirectUrl))
            httpStatus = StatusCodes.Status403Forbidden;

        context.Response.StatusCode = httpStatus;
        context.Response.ContentType = "application/json; charset=utf-8";

        var payload = new Dictionary<string, object?>
        {
            ["message"] = message,
            ["statusCode"] = statusCode
        };

        if (!string.IsNullOrEmpty(redirectUrl))
            payload["redirectUrl"] = redirectUrl;

        await context.Response.WriteAsync(JsonSerializer.Serialize(payload));
    }
}
